1: /**
2:  * Gaps between her bubbles only. Nothing is added before the first one, because
3:  * Mistral already spends 1 to 5 seconds there and a human would have been typing
4:  * through it.
5:  */
6: const FAST_MS = 20_000;
7: const SLOW_MS = 120_000;
8: 
9: export const PACE_BUDGET_MS = 2500;
10: 
11: type Band = { min: number; max: number };
12: 
13: const FAST_BAND: Band = { min: 250, max: 650 };
14: const MEDIUM_BAND: Band = { min: 600, max: 1100 };
15: const SLOW_BAND: Band = { min: 1000, max: 1600 };
16: 
17: function band(tempoGapMs: number | null): Band {
18:   if (tempoGapMs === null) return MEDIUM_BAND;
19:   if (tempoGapMs <= FAST_MS) return FAST_BAND;
20:   if (tempoGapMs <= SLOW_MS) return MEDIUM_BAND;
21:   return SLOW_BAND;
22: }
23: 
24: /**
25:  * `tempoGapMs` is how long Doc took to send this message after his previous one.
26:  * Rapid-fire from him means rapid-fire back; a message after an hour gets the
27:  * pace of someone who was doing something else.
28:  */
29: export function bubbleDelayMs(params: {
30:   tempoGapMs: number | null;
31:   chars: number;
32:   remainingBudgetMs: number;
33:   rand?: () => number;
34: }): number {
35:   if (params.remainingBudgetMs <= 0) return 0;
36:   const rand = params.rand ?? Math.random;
37:   const { min, max } = band(params.tempoGapMs);
38:   const jittered = min + rand() * (max - min);
39:   // A longer bubble would have taken longer to type.
40:   const typing = Math.min(params.chars * 4, 500);
41:   return Math.round(Math.min(jittered + typing, params.remainingBudgetMs));
42: }
43: 
44: export function sleepAbortable(ms: number, signal: AbortSignal): Promise<void> {
45:   if (ms <= 0 || signal.aborted) return Promise.resolve();
46:   return new Promise((resolve) => {
47:     const timer = setTimeout(finish, ms);
48:     signal.addEventListener("abort", finish, { once: true });
49:     function finish(): void {
50:       clearTimeout(timer);
51:       signal.removeEventListener("abort", finish);
52:       resolve();
53:     }
54:   });
55: }
56: 
57: /** Per-channel record of how fast Doc is going. */
58: export class TempoTracker {
59:   private readonly last = new Map<string, number>();
60:   private readonly gaps = new Map<string, number | null>();
61: 
62:   /** Gap since his previous message, then remembers this one. */
63:   mark(channelId: string, now = Date.now()): number | null {
64:     const prev = this.last.get(channelId) ?? null;
65:     this.last.set(channelId, now);
66:     const gap = prev === null ? null : now - prev;
67:     this.gaps.set(channelId, gap);
68:     return gap;
69:   }
70: 
71:   /** Most recent gap from mark(), for drains that run after a debounce. */
72:   lastGapMs(channelId: string): number | null {
73:     return this.gaps.get(channelId) ?? null;
74:   }
75: }
76: 
77: export const tempoTracker = new TempoTracker();
