1: /**
2:  * Reactions are the loudest cheap signal she has, and cheap is the problem: an
3:  * emoji echoing the one Doc just used reads as mirroring, not as a person
4:  * responding. The model is asked to be sparing; this enforces it.
5:  */
6: const MIN_TURNS_BETWEEN = 3;
7: const MAX_TURNS_BETWEEN = 4;
8: 
9: /** Variation selectors and skin tones make the same emoji compare unequal. */
10: function normalize(emoji: string): string {
11:   return emoji
12:     .replace(/\uFE0F|\u200D/g, "")
13:     .replace(/[\u{1F3FB}-\u{1F3FF}]/gu, "")
14:     .trim();
15: }
16: 
17: export type ReactContext = {
18:   channelId: string;
19:   emoji: string | null;
20:   docText: string;
21:   herText: string;
22:   rand?: () => number;
23: };
24: 
25: export class ReactPolicy {
26:   private readonly turnsSince = new Map<string, number>();
27:   private readonly required = new Map<string, number>();
28:   private readonly lastEmoji = new Map<string, string>();
29: 
30:   /**
31:    * Call once per delivered turn, with or without a candidate emoji, because
32:    * every turn moves the budget forward.
33:    */
34:   decide(ctx: ReactContext): string | null {
35:     const turns = (this.turnsSince.get(ctx.channelId) ?? MAX_TURNS_BETWEEN) + 1;
36:     this.turnsSince.set(ctx.channelId, turns);
37: 
38:     if (!ctx.emoji) return null;
39:     const emoji = normalize(ctx.emoji);
40:     if (!emoji) return null;
41: 
42:     if (normalize(ctx.docText).includes(emoji)) return null;
43:     if (normalize(ctx.herText).includes(emoji)) return null;
44:     if (this.lastEmoji.get(ctx.channelId) === emoji) return null;
45: 
46:     const required = this.required.get(ctx.channelId) ?? MIN_TURNS_BETWEEN;
47:     if (turns < required) return null;
48: 
49:     const rand = ctx.rand ?? Math.random;
50:     this.turnsSince.set(ctx.channelId, 0);
51:     this.required.set(
52:       ctx.channelId,
53:       rand() < 0.5 ? MIN_TURNS_BETWEEN : MAX_TURNS_BETWEEN,
54:     );
55:     this.lastEmoji.set(ctx.channelId, emoji);
56:     return ctx.emoji;
57:   }
58: }
59: 
60: export const reactPolicy = new ReactPolicy();
61: 
62: /** 0.5 to 1.5s after the first bubble, so it reads as a second thought. */
63: export function reactDelayMs(rand: () => number = Math.random): number {
64:   return Math.round(500 + rand() * 1000);
65: }
